import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"方案介绍","description":"","frontmatter":{},"headers":[],"relativePath":"web/form-page/auto-assignment/ai-content-auto-fill/solution-overview.md","filePath":"web/form-page/auto-assignment/ai-content-auto-fill/solution-overview.md"}'),d={name:"web/form-page/auto-assignment/ai-content-auto-fill/solution-overview.md"};function n(l,t,i,s,h,p){return e(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="方案介绍" tabindex="-1">方案介绍 <a class="header-anchor" href="#方案介绍" aria-label="Permalink to &quot;方案介绍&quot;">​</a></h1><h2 id="方案概述" tabindex="-1">方案概述 <a class="header-anchor" href="#方案概述" aria-label="Permalink to &quot;方案概述&quot;">​</a></h2><p>本方案通过在表单页面（EntityForm）中进行组件级扩展实现。在字段级别使用扩展属性，为目标字段追加操作按钮，并通过事件绑定实现按钮的交互逻辑。</p><h2 id="扩展组件" tabindex="-1">扩展组件 <a class="header-anchor" href="#扩展组件" aria-label="Permalink to &quot;扩展组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>终端</th><th>扩展对象</th><th>扩展页面</th><th>扩展区域</th><th>扩展组件</th><th>扩展功能</th></tr></thead><tbody><tr><td>网页端/移动端</td><td>合同申请单</td><td>表单页</td><td>主表单</td><td>合同摘要字段</td><td>新增“AI 优化”按钮，并执行内容优化逻辑</td></tr></tbody></table><h2 id="功能设计" tabindex="-1">功能设计 <a class="header-anchor" href="#功能设计" aria-label="Permalink to &quot;功能设计&quot;">​</a></h2><ol><li><p><strong>按钮设计</strong></p><p>在合同摘要字段旁增加新按钮<strong>AI 优化</strong>。</p></li><li><p><strong>按钮交互逻辑</strong></p><p>当用户单击<strong>AI 优化</strong>按钮时，获取合同摘要字段内容，在弹出的页面中显示优化结果，用户单击确定后，可以自动回填并覆盖原有内容。</p><ol><li><p>当用户单击<strong>AI 优化</strong>按钮时，系统获取“合同摘要”字段的当前内容，并在弹出的页面中展示 AI 生成的优化结果。</p></li><li><p>用户在查看优化结果后，单击“确定”按钮，即可将优化后的内容自动回填至原字段中，覆盖原有内容。</p><p>!!! note</p><pre><code>本案例在实现过程中模拟了 AI 接口返回的优化内容，实际应用中可根据业务需求接入真实的 AI 接口，以实现自动生成与回填优化结果的完整功能。
</code></pre></li></ol></li></ol><h2 id="使用的-nex-扩展能力" tabindex="-1">使用的 NEX 扩展能力 <a class="header-anchor" href="#使用的-nex-扩展能力" aria-label="Permalink to &quot;使用的 NEX 扩展能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能点</th><th>扩展能力类别</th><th>属性/函数/事件</th><th>说明</th><th>示例值/使用方式</th></tr></thead><tbody><tr><td>在<strong>合同摘要</strong>字段旁增加<strong>AI优化</strong>按钮</td><td>附加组件</td><td>属性：labelAfter</td><td>在字段旁增加自定义按钮</td><td>labelAfter: { type: &#39;button&#39;, label: &#39;AI优化&#39; }</td></tr><tr><td>设置按钮显示在字段下方</td><td>展示位置</td><td>属性：buttonLocation</td><td>控制按钮相对于字段输入框的位置</td><td>buttonLocation: &#39;bottom&#39;</td></tr><tr><td>设置按钮样式，蓝色背景、白色文字、小尺寸圆角样式</td><td>组件样式</td><td>属性：label、style（内嵌于 labelAfter）</td><td>控制按钮外观，如文字、颜色、尺寸、圆角</td><td><code>javascript type: &#39;button&#39;, label: &#39;AI优化&#39;, style: { borderRadius: &#39;28px&#39;, marginTop: &#39;5px&#39;, background: &#39;#0564f5&#39;, color: &#39;white&#39; } </code></td></tr><tr><td>单击按钮触发 AI 接口调用并展示优化结果弹窗</td><td>事件绑定</td><td>事件：onClick</td><td>定义按钮单击后的行为逻辑，可调用接口或执行函数</td><td>onClick: (e) =&gt; {...}</td></tr></tbody></table><h2 id="使用的其他能力" tabindex="-1">使用的其他能力 <a class="header-anchor" href="#使用的其他能力" aria-label="Permalink to &quot;使用的其他能力&quot;">​</a></h2><p>弹出的结果优化页面为通过 PaaS 平台页面代码功能开发的自定义页面。关于页面代码的详细信息，关于页面代码的详细信息请参考<a href="https://doc.xiaoshouyi.com/?sso-domain=login.xiaoshouyi.com#/proMan/workplaceDetail?url=%2F%2Fconcepts%2FdevelopmentPlatform_pageDevelopment_integrateManageCustomPages.html&amp;id=1436&amp;dir=output_1758873199342&amp;time=1760515755120&amp;proId=1015&amp;checkStat=undefined" target="_blank" rel="noreferrer"><strong>集成及管理自定义开发页面</strong></a>。</p>`,11)])])}const b=a(d,[["render",n]]);export{u as __pageData,b as default};
